sys_script_email.script:
(function runMailScript( /* GlideRecord */ current, /* TemplatePrinter */ template,
    /* Optional EmailOutbound */
    email, /* Optional GlideRecord */ email_action,
    /* Optional GlideRecord */
    event) {

    function formatDate(glideDate, requestedBy) {
        var user = new GlideRecord('sys_user');
        var userTimeZone = "Canada/Eastern";
        if (user.get(requestedBy)) {
            userTimeZone = user.getValue('time_zone') || userTimeZone;
        }
        var gdt = new GlideDateTime(glideDate);
        var dateString = gdt.getDisplayValue();
        var year = dateString.substring(0, 4);
        var month = dateString.substring(5, 7);
        var day = dateString.substring(8, 10);
        var time = dateString.substring(11, 16);

        var months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
        var daysOfWeek = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

        var jsDate = new Date(year, month - 1, day);
        var formattedDate = gs.getMessage(daysOfWeek[jsDate.getDay()]) + ", " + gs.getMessage(months[month - 1]) + " " + parseInt(day, 10) + ", " + year + ", " + time + " " + userTimeZone;

        return formattedDate;
    }

    var plannedStartDate = formatDate(current.getValue('start_date'), current.getValue('requested_by'));

    template.print(plannedStartDate);

})(current, template, email, email_action, event);
